 const weeklyAccuracy=weeklyHistory.length?Math.round(weeklyHistory.reduce((a,h)=>a+h.correct,0)/Math.max(1,weeklyHistory.reduce((a,h)=>a+h.total,0))*100):0
 const subjectsByName=useMemo(()=>new Map(subjects.map(s=>[s.nome,s])),[subjects])
 const subjectPerformance=useMemo(()=>{const map=new Map<string,{correct:number;wrong:number;total:number}>();for(const h of history){const x=map.get(h.subject)||{correct:0,wrong:0,total:0};x.correct+=h.correct;x.wrong+=h.wrong;x.total+=h.total;map.set(h.subject,x)}return [...map.entries()].map(([name,x])=>({name:localizedName(subjectsByName.get(name)||{nome:name},language),...x,accuracy:Math.round(x.correct/Math.max(1,x.total)*100)})).sort((a,b)=>b.total-a.total).slice(0,6)},[history,subjectsByName,language])
 const facultyNames=useMemo(()=>new Map(faculties.map(f=>[f.id,localizedName(f,language)])),[faculties,language])
 const quizCounts=useMemo(()=>{const map=new Map<string,number>();for(const q of quizSets)map.set(q.materia_id,(map.get(q.materia_id)||0)+1);return map},[quizSets])

 const courseOptions=useMemo(()=>Array.from(new Set(subjects.map(s=>s.corso_di_laurea?.trim()).filter((x):x is string=>Boolean(x)))).sort((a,b)=>a.localeCompare(b,'it')),[subjects])
 const nav=[{id:'home' as Page,label:tr('startQuiz'),icon:Target},{id:'study' as Page,label:tr('study'),icon:BookOpen},{id:'review' as Page,label:tr('reviewWrongTitleNew'),icon:Target},{id:'progress' as Page,label:tr('progress'),icon:BarChart3},{id:'leaderboard' as Page,label:tr('leaderboard'),icon:Trophy},{id:'account' as Page,label:tr('account'),icon:UserRound}]
 async function auth(e:FormEvent){e.preventDefault();if(authBusy||authLocked)return;setAuthLocked(true);window.setTimeout(()=>setAuthLocked(false),3000);if(!supabaseReady){notify(tr('missingSupabaseKey'));return}if(authMode==='register'&&!accepted){notify(tr('acceptPrivacyTerms'));return}if(authMode==='register'&&(!turnstileSiteKey||!captchaToken)){notify(tr('captchaRequired'));return}if(turnstileSiteKey&&!captchaToken){notify(tr('completeCaptcha'));return}setAuthBusy(true);try{if(authMode==='register'){if(password.length<8||!/[A-Z]/.test(password))throw new Error('La password deve avere almeno 8 caratteri e una lettera maiuscola.');const exposure=await checkPasswordExposure(password);if(exposure==='compromised')throw new Error(tr('passwordBreached'));if(exposure==='unavailable')throw new Error(tr('passwordCheckUnavailable'))}const client=requireSupabase();if(authMode==='register'){const {data,error}=await client.auth.signUp({email,password,options:{captchaToken:captchaToken||undefined,emailRedirectTo:location.origin,data:{privacy_policy_version:'2026-11-03',terms_version:'2026-11-03',accepted_privacy:accepted}}});if(error)throw error;if(data.session){await client.functions.invoke('quiz-api',{body:{action:'consent',accepted:true}});setWelcomeMessage('');notify(tr('welcomeRegistered'))}else{setWelcomeMessage('');notify(tr('confirmRegistration'))}}else if(authMode==='reset'){const {error}=await client.auth.resetPasswordForEmail(email,{redirectTo:location.origin,captchaToken:captchaToken||undefined});if(error)throw error;notify(tr('recoveryEmail'))}else{const {error}=await client.auth.signInWithPassword({email,password,options:{captchaToken:captchaToken||undefined}});if(error)throw error;const {data:sessionData}=await client.auth.getSession();const name=sessionData.session?.user.user_metadata?.display_name||sessionData.session?.user.email?.split('@')[0]||'studente';setWelcomeMessage(name);notify(tr('welcomeBackUser')+', '+name);setPage('home');window.history.pushState({},'','/quiz')}}catch(err){notify(err instanceof Error?err.message:tr('genericOperationFailed'))}finally{setAuthBusy(false);setCaptchaToken('');setCaptchaReset(v=>v+1)}}
 async function saveNewPassword(e:FormEvent){
  e.preventDefault();
  if(authBusy)return;
  if(password.length<8||!/[A-Z]/.test(password)){notify('La password deve avere almeno 8 caratteri e una lettera maiuscola.');return}
  if(password!==passwordConfirm){notify(tr('passwordsDoNotMatch'));return}
  setAuthBusy(true);
  try{
   const exposure=await checkPasswordExposure(password);
   if(exposure==='compromised')throw new Error(tr('passwordBreached'));
   if(exposure==='unavailable')throw new Error(tr('passwordCheckUnavailable'));
   const client=requireSupabase();
   const {error}=await client.auth.updateUser({password});
   if(error)throw error;
   setPasswordRecoveryOpen(false);setPassword('');setPasswordConfirm('');
   notify(tr('passwordUpdated'));
  }catch(err){notify(err instanceof Error?err.message:tr('genericOperationFailed'))}
  finally{setAuthBusy(false)}
 }
 async function googleAuth(){if(authBusy||!supabaseReady){if(!supabaseReady)notify(tr('accessNotConfigured'));return}setAuthBusy(true);try{const client=requireSupabase();const {error}=await client.auth.signInWithOAuth({provider:"google",options:{redirectTo:location.origin}});if(error)throw error}catch(err){notify(err instanceof Error?err.message:tr('googleAccessUnavailable'));setAuthBusy(false)}}
 async function logout(){try{if(supabase){const {error}=await supabase.auth.signOut({scope:'local'});if(error)throw error}}catch(err){notify(err instanceof Error?err.message:tr('logoutFailed'));return}Object.keys(localStorage).filter(k=>k.startsWith('smlquiz.')).forEach(k=>localStorage.removeItem(k));Object.keys(sessionStorage).filter(k=>k.startsWith('smlquiz.')).forEach(k=>sessionStorage.removeItem(k));setUser(null);setHistory([]);setWallet({paidCredits:0,freeUsed:0,freeRemaining:5,ledger:[]});setAttemptId(null);setQuestions([]);setSubject(null);setIndex(0);setChoice(null);setAnswerFeedback(null);setRevealed(false);setCorrect(0);setWrong(0);setSeconds(0);setStarted(null);setStreak({current_streak:0,longest_streak:0});setAchievements([]);setWeakTopics([]);setLeaderboardRows([]);setDisplayName('');setLeaderboardOptIn(false);setSavedQuestions([]);setReviewQuestions([]);setWrongQuestions([]);setPage('home');setWelcomeMessage('');notify(tr('logoutSuccess'))}
 async function refreshWallet(){if(!supabase||!user)return;const [w,s]=await Promise.all([supabase.functions.invoke('quiz-api',{body:{action:'wallet'}}),supabase.functions.invoke('quiz-api',{body:{action:'streaks'}})]);if(!w.error&&w.data)setWallet(w.data);if(!s.error&&s.data){setStreak(s.data.streak);setAchievements(s.data.achievements||[])}}
 async function redeemCoupon(e:FormEvent){e.preventDefault();if(!supabase||!couponCode.trim())return;setCouponBusy(true);try{const {data,error}=await supabase.functions.invoke('quiz-api',{body:{action:'coupon',code:couponCode.trim()}});if(error)throw error;if(data?.error)throw new Error(data.error);setCouponCode('');notify(tr('couponApplied').replace('{n}',String(data.credits_added)));void refreshWallet()}catch(err){notify(err instanceof Error?err.message:tr('invalidCoupon'))}finally{setCouponBusy(false)}}
 async function sendQuestionReport(e:FormEvent){e.preventDefault();if(!supabase||!current||!attemptId)return;try{const {data,error}=await supabase.functions.invoke('quiz-api',{body:{action:'report',questionId:current.id,category:reportCategory,details:reportDetails}});if(error)throw error;if(data?.error)throw new Error(data.error);setReportOpen(false);setReportDetails('');notify(tr('reportSent'))}catch(err){notify(err instanceof Error?err.message:tr('reportFailed'))}}
 async function buyPackage(priceId:string){
  if(!digitalConsent){notify(tr('digitalConsentRequired'));return}
  if(!supabase||!user){go('account');notify(tr('accountSignInRequired'));return}
  try{
   const {data,error}=await supabase.functions.invoke('stripe-checkout',{body:{priceId,digitalContentConsent:true,digitalContentConsentAt:new Date().toISOString()}});
   if(error){
    let message=error.message||tr('checkoutUnavailable');
    const response=(error as unknown as {context?:Response}).context;
    if(response){try{const payload=await response.clone().json();if(typeof payload?.error==='string')message=payload.error}catch{}}
    throw new Error(message);
   }
   if(data?.error)throw new Error(data.error);
   if(typeof data?.url!=='string'||!data.url.startsWith('https://checkout.stripe.com/'))throw new Error(tr('checkoutUnavailable'));
   window.location.assign(data.url);
  }catch(err){notify(err instanceof Error?err.message:tr('checkoutUnavailable'))}
 }
 async function saveProfile(e:FormEvent){e.preventDefault();if(!supabase||!user)return;setProfileBusy(true);try{const {data,error}=await supabase.functions.invoke('quiz-api',{body:{action:'profile',mode:'update',displayName,language,leaderboardOptIn,universityName,universityCity,universityCourse}});if(error)throw error;if(data?.error)throw new Error(data.error);notify(tr('profileUpdated'))}catch(err){notify(err instanceof Error?err.message:tr('profileSaveFailed'))}finally{setProfileBusy(false)}}
