 async function refreshWrongQuestions(){if(!supabase||!user)return;const {data,error}=await supabase.functions.invoke('quiz-api',{body:{action:'wrong-questions'}});if(error){notify(error.message);return}if(data?.questions)setReviewQuestions((data.questions as Question[]).map(q=>localizedQuestion(q,language)))}
 async function saveUniversityProfile(){if(!supabase||!user)return;if(!universityName.trim()||!universityCity.trim()||!universityCourse.trim()){notify(tr('universityRequired'));return}setProfileBusy(true);try{const {data,error}=await supabase.functions.invoke('quiz-api',{body:{action:'profile',mode:'update',displayName,language,leaderboardOptIn,universityName,universityCity,universityCourse}});if(error)throw error;if(data?.error)throw new Error(data.error);await loadLeaderboard();notify(leaderboardOptIn?tr('universitySaved'):tr('universitySavedOptOut'))}catch(err){notify(err instanceof Error?err.message:tr('universitySaveFailed'))}finally{setProfileBusy(false)}}
